const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card { box-sizing: border-box; height: 100%; min-width: 0; min-height: 0; color: var(--ink); font: 13px/1.4 system-ui, -apple-system, \"PingFang SC\", \"Microsoft YaHei\", sans-serif; }\n.wrap { box-sizing: border-box; height: 100%; min-width: 0; min-height: 0; display: flex; flex-direction: column; gap: 6px; padding: 10px; overflow: hidden; }\n.hd { flex: none; display: flex; align-items: center; justify-content: space-between; gap: 6px; min-width: 0; }\n.ttl { font-weight: 700; font-size: 14px; white-space: nowrap; }\n.tabs { display: none; gap: 4px; }\n.tab { font: inherit; font-size: 12px; padding: 3px 9px; border-radius: 999px; border: 1px solid var(--line); background: var(--panel-paper); color: var(--ink); cursor: pointer; white-space: nowrap; }\n.tab.on { background: var(--accent); border-color: var(--accent); color: var(--on-accent); font-weight: 600; }\n\n.body { flex: 1; min-height: 0; min-width: 0; display: grid; gap: 8px; grid-template-columns: minmax(0, 1fr); grid-template-rows: minmax(0, 1fr); }\n.form, .res { min-height: 0; min-width: 0; display: flex; flex-direction: column; gap: 6px; }\n.scroll { flex: 1; min-height: 0; overflow-y: auto; overflow-x: hidden; display: flex; flex-direction: column; gap: 8px; padding-right: 2px; }\n.act { flex: none; display: flex; flex-direction: column; gap: 5px; }\n\n.pair { display: grid; grid-template-columns: minmax(0, 1fr); gap: 8px; }\n.fld { display: flex; flex-direction: column; gap: 3px; min-width: 0; }\n.lb { font-size: 11px; color: var(--muted); }\n.inp { box-sizing: border-box; width: 100%; min-width: 0; font: inherit; font-size: 12.5px; padding: 6px 8px; border: 1px solid var(--line); border-radius: 8px; background: var(--panel-paper); color: var(--ink); outline: none; }\n.inp:focus { border-color: var(--accent); }\n.inp::placeholder { color: var(--muted); }\n.ta { resize: none; line-height: 1.35; display: block; }\n\n.chips { display: flex; flex-wrap: wrap; gap: 4px; }\n.chip { font: inherit; font-size: 12px; min-height: 26px; padding: 3px 10px; border-radius: 999px; border: 1px solid var(--line); background: var(--panel-paper); color: var(--ink); cursor: pointer; white-space: nowrap; }\n.chip.on { background: var(--accent); border-color: var(--accent); color: var(--on-accent); font-weight: 600; }\n\n.go { font: inherit; font-weight: 600; width: 100%; min-height: 34px; padding: 7px 10px; border: 0; border-radius: 10px; background: var(--accent); color: var(--on-accent); cursor: pointer; }\n.note { position: relative; display: flex; gap: 6px; align-items: flex-start; box-sizing: border-box; max-height: 76px; overflow-y: auto; padding: 6px 8px; border-radius: 8px; border-left: 3px solid var(--accent); background: var(--soft); color: var(--ink); font-size: 11.5px; line-height: 1.4; }\n.note.warn { border-left-color: var(--accent-alt); }\n.nt { flex: 1; min-width: 0; overflow-wrap: anywhere; }\n.x { flex: none; font: inherit; line-height: 1; width: 20px; height: 20px; padding: 0; border: 0; border-radius: 50%; background: transparent; color: var(--muted); cursor: pointer; }\n\n.rhd { flex: none; display: flex; align-items: center; justify-content: space-between; gap: 6px; min-width: 0; }\n.rt { font-weight: 600; font-size: 12.5px; white-space: nowrap; }\n.ops { display: inline-flex; align-items: center; gap: 2px; flex: none; }\n.lnk { font: inherit; font-size: 12px; padding: 3px 7px; border: 0; border-radius: 6px; background: transparent; color: var(--muted); cursor: pointer; white-space: nowrap; }\n.lnk.main { color: var(--accent); font-weight: 600; }\n.msg { flex: none; padding: 4px 8px; border-radius: 8px; border-left: 3px solid var(--accent-alt); background: var(--soft); font-size: 11.5px; }\n.list { flex: 1; min-height: 0; overflow-y: auto; overflow-x: hidden; display: flex; flex-direction: column; gap: 6px; padding-right: 2px; }\n.it { flex: none; box-sizing: border-box; padding: 7px 9px; border: 1px solid var(--line); border-radius: 10px; background: var(--panel-paper); display: flex; flex-direction: column; gap: 4px; min-width: 0; }\n.it.ed { border-color: var(--accent); }\n.txt { font-size: 13.5px; font-weight: 600; line-height: 1.4; overflow-wrap: anywhere; white-space: pre-wrap; }\n.meta { display: flex; align-items: center; justify-content: space-between; gap: 6px; flex-wrap: wrap; }\n.cnt { font-size: 11px; color: var(--muted); }\n.cnt.over { color: var(--accent); font-weight: 600; }\n.empty { padding: 10px 4px; font-size: 12px; color: var(--muted); line-height: 1.5; }\n\n/* 3x3 \u5c0f\u5361\uff1a\u8bbe\u7f6e / \u6807\u9898 \u5206\u9875\uff0c\u751f\u6210\u6309\u94ae\u56fa\u5b9a\u5728\u5e95\u90e8 */\n.card[data-size=\"3x3\"] .tabs { display: flex; }\n.card[data-size=\"3x3\"] .wrap { padding: 8px; gap: 5px; }\n.card[data-size=\"3x3\"] .ttl { font-size: 13px; }\n.card[data-size=\"3x3\"] .body[data-view=\"form\"] .res { display: none; }\n.card[data-size=\"3x3\"] .body[data-view=\"res\"] .form { display: none; }\n.card[data-size=\"3x3\"] .inp { padding: 5px 7px; }\n.card[data-size=\"3x3\"] .chip { padding: 2px 8px; min-height: 24px; }\n\n/* 6x3 \u6a2a\u5361\uff1a\u5de6\u8bbe\u7f6e\u53f3\u7ed3\u679c */\n.card[data-size=\"6x3\"] .body { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); grid-template-rows: minmax(0, 1fr); gap: 12px; }\n.card[data-size=\"6x3\"] .wrap { padding: 8px 10px; gap: 4px; }\n\n/* 3x6 \u7ad6\u5361\uff1a\u4e0a\u8bbe\u7f6e\u4e0b\u7ed3\u679c */\n.card[data-size=\"3x6\"] .body { grid-template-columns: minmax(0, 1fr); grid-template-rows: minmax(0, 1.15fr) minmax(0, 1fr); gap: 8px; }\n\n/* 6x6 \u5927\u5361\uff1a\u4e0a\u8bbe\u7f6e\uff08\u4e24\u680f\u8f93\u5165\uff09\u4e0b\u7ed3\u679c */\n.card[data-size=\"6x6\"] .body { grid-template-columns: minmax(0, 1fr); grid-template-rows: minmax(0, 0.9fr) minmax(0, 1fr); gap: 10px; }\n.card[data-size=\"6x6\"] .pair { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }\n.card[data-size=\"6x6\"] .wrap { padding: 14px; gap: 8px; }\n.card[data-size=\"6x6\"] .ttl { font-size: 16px; }\n";
var TONES = ['种草', '干货', '搞笑', '治愈', '反差', '专业'];
var COUNTS = [3, 5, 8, 10];
var LIMIT = 20;

function norm(s) {
  var c = (s && s.cfg) || {};
  return {
    cfg: {
      topic: String(c.topic || ''),
      audience: String(c.audience || ''),
      tone: TONES.indexOf(c.tone) >= 0 ? c.tone : '种草',
      count: COUNTS.indexOf(c.count) >= 0 ? c.count : 5
    },
    titles: Array.isArray(s && s.titles) ? s.titles : []
  };
}

function initialize(s) {
  if (s && s.cfg && Array.isArray(s.titles)) return s;
  return Object.assign({}, s, norm(s));
}

function textLen(t) {
  return Array.from(t || '').length;
}

function mount(ctx) {
  const { root, el, state, ui, update, commit, redraw, uid } = ctx;
  const data = norm(state);
  if (!ui.cfg) ui.cfg = Object.assign({}, data.cfg);
  if (!ui.view) ui.view = 'form';
  const cfg = ui.cfg;

  // 每次保存都带上最新的设置草稿，保留其他记录
  const withCfg = function (st) {
    const n = norm(st);
    return Object.assign({}, st, { cfg: Object.assign({}, n.cfg, ui.cfg), titles: n.titles });
  };
  const withTitles = function (st, fn) {
    const w = withCfg(st);
    return Object.assign({}, w, { titles: fn(w.titles) });
  };
  const nextUi = function () {
    return Object.assign({}, ui, { editId: null, editText: '', delId: null, resMsg: '' });
  };

  const onGenerate = function () {
    if (!String(cfg.topic).trim()) {
      ui.notice = { kind: 'warn', text: '请先填写主题，再点生成。' };
      redraw();
      return;
    }
    ui.notice = {
      kind: 'info',
      text: '暂未接入 AI 推理，没有生成标题。你的设置已保存，接入后可直接使用；现在可在标题区手写。'
    };
    update(withCfg).catch(function () {
      ui.notice = { kind: 'warn', text: '设置保存失败，请重试。' };
      redraw();
    });
  };

  const onAnother = function () {
    ui.resMsg = '暂未接入 AI 推理，无法换一批。已有标题不受影响，仍可直接修改。';
    redraw();
  };

  const chip = function (label, on, handler) {
    return el('button', {
      type: 'button',
      class: 'chip' + (on ? ' on' : ''),
      'aria-pressed': on ? 'true' : 'false',
      onclick: handler
    }, label);
  };

  const field = function (label, key, placeholder) {
    return el('label', { class: 'fld' },
      el('span', { class: 'lb' }, label),
      el('input', {
        type: 'text',
        class: 'inp',
        value: cfg[key],
        placeholder: placeholder,
        oninput: function (e) { cfg[key] = e.target.value; }
      })
    );
  };

  const buildForm = function () {
    const tones = el('div', { class: 'chips' });
    TONES.forEach(function (t) {
      tones.append(chip(t, cfg.tone === t, function () {
        cfg.tone = t;
        update(withCfg);
      }));
    });
    const counts = el('div', { class: 'chips' });
    COUNTS.forEach(function (n) {
      counts.append(chip(n + ' 个', cfg.count === n, function () {
        cfg.count = n;
        update(withCfg);
      }));
    });
    const scroll = el('div', { class: 'scroll' },
      el('div', { class: 'pair' },
        field('主题', 'topic', '例如：周末在家做低卡早餐'),
        field('想给谁看', 'audience', '例如：25 岁的职场新人')
      ),
      el('div', { class: 'fld' }, el('span', { class: 'lb' }, '语气'), tones),
      el('div', { class: 'fld' }, el('span', { class: 'lb' }, '数量'), counts)
    );
    const act = el('div', { class: 'act' });
    if (ui.notice) {
      act.append(el('div', { class: 'note ' + ui.notice.kind, role: 'status' },
        el('span', { class: 'nt' }, (ui.notice.kind === 'warn' ? '注意：' : '提示：') + ui.notice.text),
        el('button', {
          type: 'button',
          class: 'x',
          'aria-label': '关闭提示',
          onclick: function () { ui.notice = null; redraw(); }
        }, '×')
      ));
    }
    act.append(el('button', { type: 'button', class: 'go', onclick: onGenerate }, '让 AI 生成标题'));
    return el('section', { class: 'form' }, scroll, act);
  };


  const fail = function () {
    ui.resMsg = '保存失败，请重试。';
    redraw();
  };

  const saveEdit = function () {
    const text = String(ui.editText || '').trim();
    if (!text) {
      ui.resMsg = '标题不能为空。';
      redraw();
      return;
    }
    const id = ui.editId;
    commit(function (st) {
      return withTitles(st, function (list) {
        if (id === 'new') return [{ id: uid(), text: text }].concat(list);
        return list.map(function (t) { return t.id === id ? Object.assign({}, t, { text: text }) : t; });
      });
    }, nextUi()).catch(fail);
  };

  const removeTitle = function (id) {
    if (ui.delId !== id) {
      ui.delId = id;
      redraw();
      return;
    }
    commit(function (st) {
      return withTitles(st, function (list) { return list.filter(function (t) { return t.id !== id; }); });
    }, nextUi()).catch(fail);
  };

  const counter = function (n) {
    const over = n > LIMIT;
    return el('span', { class: 'cnt' + (over ? ' over' : '') },
      n + '/' + LIMIT + ' 字' + (over ? '，超出 ' + (n - LIMIT) + ' 字' : ''));
  };

  const editBox = function () {
    const cnt = counter(textLen(ui.editText));
    const ta = el('textarea', {
      class: 'inp ta',
      rows: '2',
      placeholder: '写下标题，回车保存',
      value: ui.editText || '',
      oninput: function (e) {
        ui.editText = e.target.value;
        const n = textLen(ui.editText);
        cnt.textContent = n + '/' + LIMIT + ' 字' + (n > LIMIT ? '，超出 ' + (n - LIMIT) + ' 字' : '');
        cnt.className = 'cnt' + (n > LIMIT ? ' over' : '');
      },
      onkeydown: function (e) {
        if (e.key === 'Enter' && !e.shiftKey) {
          e.preventDefault();
          saveEdit();
        }
      }
    });
    return el('div', { class: 'it ed' }, ta,
      el('div', { class: 'meta' }, cnt,
        el('span', { class: 'ops' },
          el('button', { type: 'button', class: 'lnk', onclick: function () { ui.editId = null; ui.resMsg = ''; redraw(); } }, '取消'),
          el('button', { type: 'button', class: 'lnk main', onclick: saveEdit }, '保存')
        )
      )
    );
  };

  const itemView = function (t) {
    const confirming = ui.delId === t.id;
    return el('div', { class: 'it' },
      el('div', { class: 'txt' }, t.text),
      el('div', { class: 'meta' }, counter(textLen(t.text)),
        el('span', { class: 'ops' },
          el('button', {
            type: 'button',
            class: 'lnk',
            onclick: function () { ui.editId = t.id; ui.editText = t.text; ui.delId = null; ui.resMsg = ''; redraw(); }
          }, '修改'),
          el('button', {
            type: 'button',
            class: 'lnk' + (confirming ? ' main' : ''),
            onclick: function () { removeTitle(t.id); }
          }, confirming ? '确认删除' : '删除')
        )
      )
    );
  };

  const buildResults = function () {
    const list = el('div', { class: 'list' });
    if (ui.editId === 'new') list.append(editBox());
    data.titles.forEach(function (t) {
      list.append(ui.editId === t.id ? editBox() : itemView(t));
    });
    if (!data.titles.length && ui.editId !== 'new') {
      list.append(el('div', { class: 'empty' }, '还没有标题。AI 生成接入前，可以点「手写」自己写一条，之后随时修改。'));
    }
    const hd = el('div', { class: 'rhd' },
      el('span', { class: 'rt' }, '标题版本 ' + data.titles.length),
      el('span', { class: 'ops' },
        el('button', { type: 'button', class: 'lnk', onclick: onAnother }, '换一批'),
        el('button', {
          type: 'button',
          class: 'lnk main',
          onclick: function () { ui.editId = 'new'; ui.editText = ''; ui.delId = null; ui.resMsg = ''; ui.view = 'res'; redraw(); }
        }, '＋ 手写')
      )
    );
    const sec = el('section', { class: 'res' }, hd);
    if (ui.resMsg) sec.append(el('div', { class: 'msg', role: 'alert' }, '提示：' + ui.resMsg));
    sec.append(list);
    return sec;
  };

  const tab = function (key, label) {
    return el('button', {
      type: 'button',
      class: 'tab' + (ui.view === key ? ' on' : ''),
      'aria-pressed': ui.view === key ? 'true' : 'false',
      onclick: function () { ui.view = key; redraw(); }
    }, label);
  };

  const render = function () {
    const wrap = el('div', { class: 'wrap' },
      el('div', { class: 'hd' },
        el('span', { class: 'ttl' }, '小红书标题'),
        el('div', { class: 'tabs' }, tab('form', '设置'), tab('res', '标题 ' + data.titles.length))
      ),
      el('div', { class: 'body', 'data-view': ui.view }, buildForm(), buildResults())
    );
    root.append(wrap);
  };

  render();
}

